// features/vendor-lifecycle.feature: "Search ignores case and matches part of a name"
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("Search ignores case and matches part of a name", { tag: "@LIF-13" }, async ({ apiAs, factory }) => {
  // Arrange
  const name = uniqueName("Zephyrine Cold Storage");
  const vendor = await factory.vendor({ as: "member", name });
  const member = await apiAs("member");

  // Act
  const response = await member.get("/api/vendors", { params: { q: "COLD stor", limit: 100 } });

  // Assert
  const page = await expectStatus<{ items: { id: string; name: string }[]; total: number }>(response, 200);
  const match = page.items.find((item) => item.id === vendor.id);
  expect(match, `vendor "${name}" should be in results for "COLD stor"`).toBeDefined();
  expect(match?.name).toBe(name);
});
